using System.Linq;
using UnityEngine;
using UnityEngine.UI;
namespace ROM.UI.Gameplay {
[DefaultExecutionOrder(1200)]public sealed class RiftHUDIntegratedBar:MonoBehaviour {
 public RectTransform Root{get;private set;}RiftGameplayHUD hud;bool potionsMounted;
 public const float Width=680,Height=128,Bottom=32;
 public static RectTransform Rect(Transform parent,string name,float x,float y,float w,float h){var r=new GameObject(name,typeof(RectTransform)).GetComponent<RectTransform>();r.SetParent(parent,false);Place(r,x,y,w,h);return r;}
 public static void Place(RectTransform r,float x,float y,float w,float h){r.anchorMin=r.anchorMax=r.pivot=Vector2.up;r.anchoredPosition=new Vector2(x,-y);r.sizeDelta=new Vector2(w,h);r.localScale=Vector3.one;}
 static void Stretch(RectTransform r,float inset=0){r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.pivot=new Vector2(.5f,.5f);r.offsetMin=Vector2.one*inset;r.offsetMax=-Vector2.one*inset;r.localScale=Vector3.one;}
 void Awake(){hud=GetComponent<RiftGameplayHUD>();Root=Rect(hud.Design,"Integrated action dock",0,0,Width,Height);Root.anchorMin=Root.anchorMax=new Vector2(.5f,0);Root.pivot=new Vector2(.5f,0);Root.anchoredPosition=new Vector2(0,Bottom);Root.gameObject.AddComponent<RiftHUDChrome>().raycastTarget=false;
  var hotbar=hud.Design.Find("Compact ability hotbar") as RectTransform;hotbar.SetParent(Root,false);Place(hotbar,122,9,546,112);
  var retained=hud.Abilities.Select(x=>x.transform).Concat(hud.KeyLabels.Select(x=>x.transform.parent)).ToArray();foreach(Transform child in hotbar)if(!retained.Contains(child))child.gameObject.SetActive(false);
  for(int i=0;i<hud.Abilities.Length;i++){var slot=hud.Abilities[i];Place((RectTransform)slot.transform,i*78,0,72,78);var frame=slot.GetComponent<RiftHUDGraphic>();frame.Border=new Color(.58f,.4f,.76f);frame.Thickness=1.2f;frame.Bottom=new Color(.025f,.023f,.04f,.94f);Place(hud.Icons[i].rectTransform,4,4,64,70);hud.Icons[i].preserveAspect=false;Place(hud.Cooldowns[i].rectTransform,4,4,64,70);Place(hud.Timers[i].rectTransform,0,14,72,45);var cap=(RectTransform)hud.KeyLabels[i].transform.parent;Place(cap,i*78+20,86,32,24);var g=cap.GetComponent<RiftHUDGraphic>();if(g)g.enabled=false;Stretch(hud.KeyLabels[i].rectTransform);hud.KeyLabels[i].fontSize=16;var locked=slot.transform.Find("Lock") as RectTransform;if(locked){locked.anchorMin=locked.anchorMax=locked.pivot=new Vector2(.5f,.5f);locked.anchoredPosition=Vector2.zero;}}
  var micro=Rect(hud.Design,"Detached lower right micromenu",0,0,224,32);micro.anchorMin=micro.anchorMax=Vector2.right;micro.pivot=Vector2.right;micro.anchoredPosition=new Vector2(-20,46);var general=hud.Design.Find("General menu shortcuts") as RectTransform;general.SetParent(micro,false);Place(general,96,0,128,32);foreach(var b in general.GetComponentsInChildren<Button>()){var br=(RectTransform)b.transform;br.sizeDelta=new Vector2(32,32);br.anchoredPosition=new Vector2(br.GetSiblingIndex()*32,0);var icon=b.transform.Find("Readable general action icon") as RectTransform;if(icon)icon.sizeDelta=new Vector2(24,24);}
  var shortcuts=hud.Design.Find("Gameplay shortcuts");var buttons=shortcuts.GetComponentsInChildren<Button>(true);int index=0;foreach(var button in buttons){if(!button.gameObject.activeSelf)continue;button.transform.SetParent(micro,false);Place((RectTransform)button.transform,index*32,0,32,32);var old=button.GetComponent<RiftHUDGraphic>();if(old)old.enabled=false;var oldIcon=button.transform.Find("Gold icon");if(oldIcon)oldIcon.gameObject.SetActive(false);var chrome=Rect(button.transform,"Utility inset frame",3,3,26,26).gameObject.AddComponent<RiftHUDChrome>();chrome.Fill=new Color(.04f,.035f,.065f,.45f);chrome.Cut=5;chrome.Accents=false;chrome.Border=new Color(.43f,.35f,.56f,.8f);chrome.raycastTarget=true;var hit=Rect(button.transform,"Utility padded hit target",0,0,32,32).gameObject.AddComponent<Image>();hit.color=Color.clear;hit.raycastTarget=true;hit.transform.SetAsFirstSibling();button.targetGraphic=chrome;
   int id=button.name.Contains("I")?0:button.name.Contains("K")?1:2;DrawGlyph(button.transform,id);var glyph=(RectTransform)button.transform.Find("Utility glyph");glyph.anchoredPosition=new Vector2(2,-2);glyph.localScale=Vector3.one*.55f;var label=id==0?hud.ShortcutLabels[0]:id==1?hud.ShortcutLabels[2]:hud.ShortcutLabels[4];label.transform.SetParent(button.transform,false);Place(label.rectTransform,-4,58,60,22);label.fontSize=11;label.color=new Color(.94f,.91f,1);label.gameObject.SetActive(false);var tip=button.GetComponent<RiftTooltipTrigger>();if(!tip)tip=button.gameObject.AddComponent<RiftTooltipTrigger>();tip.Ability=-1;tip.Title=id==0?"Inventario":id==1?"Habilidades":"Talentos";tip.Description="Abrir "+tip.Title.ToLowerInvariant()+".";tip.ActionId=id==0?"Inventory":id==1?"Abilities":"Talents";index++;}
  shortcuts.gameObject.SetActive(false);
 }
 void DrawGlyph(Transform parent,int kind){var root=Rect(parent,"Utility glyph",34,16,50,45);if(kind==0){var body=Rect(root,"Bag body",6,11,38,32).gameObject.AddComponent<RiftHUDChrome>();body.Fill=new Color(.39f,.22f,.12f,.98f);body.Border=new Color(.78f,.52f,.3f);body.Cut=5;body.raycastTarget=false;Line(root,new Vector2(16,-12),new Vector2(16,-4),2,body.Border);Line(root,new Vector2(16,-4),new Vector2(33,-4),2,body.Border);Line(root,new Vector2(33,-4),new Vector2(33,-12),2,body.Border);var pocket=Rect(root,"Bag pocket",14,24,22,13).gameObject.AddComponent<RiftHUDChrome>();pocket.Fill=new Color(.5f,.3f,.17f);pocket.Border=body.Border;pocket.Cut=2;pocket.Accents=false;pocket.raycastTarget=false;return;}if(kind==1){var cover=Rect(root,"Book cover",3,4,43,34).gameObject.AddComponent<RiftHUDChrome>();cover.Fill=new Color(.26f,.12f,.48f,.95f);cover.Border=new Color(.73f,.47f,.97f);cover.Cut=4;cover.raycastTarget=false;Line(root,new Vector2(10,-8),new Vector2(10,-33),2,new Color(.77f,.65f,.92f));for(int i=0;i<3;i++)Line(root,new Vector2(17,-12-i*6),new Vector2(37,-12-i*6),1,new Color(.8f,.72f,.95f));return;}var c=new Color(.75f,.59f,.96f);foreach(var pair in new[]{new[]{new Vector2(25,-5),new Vector2(25,-22)},new[]{new Vector2(25,-22),new Vector2(8,-37)},new[]{new Vector2(25,-22),new Vector2(42,-37)}})Line(root,pair[0],pair[1],2,c);foreach(var point in new[]{new Vector2(25,-5),new Vector2(25,-22),new Vector2(8,-37),new Vector2(42,-37)}){var node=Rect(root,"Talent node",point.x-5,-point.y-5,10,10).gameObject.AddComponent<RiftHUDGraphic>();node.Shape=HUDShape.Disc;node.color=c;node.raycastTarget=false;}}
 static void Line(Transform parent,Vector2 a,Vector2 b,float width,Color c){var r=Rect(parent,"Glyph line",a.x,-a.y,Vector2.Distance(a,b),width);r.pivot=new Vector2(0,.5f);r.localRotation=Quaternion.Euler(0,0,Mathf.Atan2((b-a).y,(b-a).x)*Mathf.Rad2Deg);var image=r.gameObject.AddComponent<Image>();image.color=c;image.raycastTarget=false;}
 void LateUpdate(){if(!potionsMounted){var field=FindFirstObjectByType<RiftFieldUI>();if(field&&field.PotionRoot){field.PotionRoot.SetParent(Root,false);Place(field.PotionRoot,16,24,96,94);for(int i=0;i<2;i++){var button=field.Potions[i];Place((RectTransform)button.transform,i*48,0,42,52);var bg=button.GetComponent<RiftHUDGraphic>();if(bg){bg.Shape=HUDShape.Slot;bg.Border=new Color(.46f,.35f,.6f);bg.Bottom=new Color(.03f,.025f,.045f,.9f);}Place(field.Keys[i].rectTransform,-8,57,60,22);}potionsMounted=true;}}
  string[] titles={"Inventario","Habilidades","Talentos"};int[] indices={0,2,4};string[] actions={"Inventory","Abilities","Talents"};for(int i=0;i<3;i++)hud.ShortcutLabels[indices[i]].text="["+MultiFPS.RiftControls.ActionLabel(actions[i])+"]";
 }
}
}
